"""Reserve independently worded multi-turn requirements before inference."""
import json,hashlib
from pathlib import Path
R=Path(__file__).parent
read=lambda p:list(map(json.loads,p.read_text().splitlines()))
system=next(x['messages'][0] for x in read(R/'acquisition.jsonl') if x['task']=='draft')
rows=[]
def add(id,turns,desc,title,questions=None,literals=None):
 assert len(turns)%2==1
 row={'id':id,'task':'draft','messages':[system]+[{'role':'user' if i%2==0 else 'assistant','content':s} for i,s in enumerate(turns)]+[{'role':'assistant','content':json.dumps({'description':desc,'questions':questions or [],'summary':title},ensure_ascii=False)}]}
 if literals:row['required_literals']=literals
 rows.append(row)
add('withdrawn-latest',['Счёт поставщику можно отправить. В нём номер заказа.','Номер заказа заменить?','Да, на номер поставки.','Нужна отправка после правки?','Сейчас нет: прежнее согласие отзываю.','Правку тоже откатить?','Номер поставки оставить. Отправку отменить, сохранить черновик. Составь требования.'],'Сохранить черновик счёта с номером поставки вместо номера заказа. Поставщику не отправлять: прежнее разрешение отозвано.','Черновик счёта')
add('only-one-recipient',['Есть две одинаковые памятки: для мастера и ученика. Обе только подготовить.','Разрешить обе отправки?','Нет, разрешаю лишь мастеру.','Ученику добавить упражнение?','Нет, ничего дополнительного.','Какие требования записать?','Одинаковые памятки и отдельные разрешения. Ученику отправку не разрешаю.'],'Подготовить две одинаковые памятки для мастера и ученика без дополнительных упражнений. Мастеру отправка разрешена. Ученику не отправлять.','Две памятки')
add('independent-field-cancels',['В карточке две правки: request_key заменить на review_key, client_key заменить на account_key.','Обе выполнить?','Пока да.','Что отменяется?','Только замена client_key.','Значит, request_key оставить?','Нет, для него правка остаётся. Укажи итоговые поля.'],'Использовать review_key вместо request_key. Поле client_key сохранить без замены на account_key.','Поля карточки')
add('preserve-and-add',['В анкете поля «Отдел» и «Группа». Планировали удалить отдел и добавить «Служба».','Удаление подтверждено?','Не подтверждено: отдел должен остаться.','Службу тогда не добавлять?','Добавить.','Группа нужна?','Да. Оформи окончательный состав.'],'Сохранить поля «Отдел» и «Группа», добавить поле «Служба». Отдел не удалять.','Поля анкеты',literals=['Отдел','Группа','Служба'])
add('verbatim-name',['Задача называется «Счёт_DEV-0008», файл report_08.csv уже существует.','Исправить название на Счет_dev-8?','Нет, имя должно совпадать посимвольно с первым вариантом.','Файл переименовать под задачу?','Не надо, имя файла сохранить.','О чём задача?','Зафиксируй точные имена и запрет их нормализации.'],'Сохранить имя задачи «Счёт_DEV-0008» посимвольно, включая регистр, ё и нули. Имя файла report_08.csv сохранить. Нормализацию имён не выполнять.','Точные имена',literals=['Счёт_DEV-0008','report_08.csv'])
add('no-invented-columns',['Нужна выгрузка перечня товаров в TSV вручную.','Добавить цену и остаток?','Я состав столбцов ещё не согласовал.','Сделать ZIP?','Нет.','Утверждаем столбцы из моего предложения?','Нет, ни цену, ни остаток не добавляй сам. Оформи и оставь вопрос о столбцах.'],'Реализовать ручную выгрузку перечня товаров в TSV без ZIP. Состав столбцов не согласован; цену и остаток без согласования не добавлять.','Выгрузка товаров',['Какие столбцы включить в выгрузку?'])
add('return-from-other-topic',['Виджет показывает число отменённых заказов. Номера телефонов скрывать.','Что ещё?','Для соседнего проекта обсудим смену шрифта.','Шрифт включить в эту задачу?','Нет, другой проект.','Телефоны тогда показать?','Нет. Запиши только требования к виджету.'],'Виджет должен показывать число отменённых заказов и скрывать номера телефонов. Смену шрифта другого проекта в задачу не включать.','Виджет заказов')
add('boundary-language',['Принимать давление от -35 до -9 включительно.','Есть поправка?','-35 теперь не допускается, всё строго выше него. Верхний предел не меняется.','-9 отклоняем?','Нет, -9 допустимо.','Дроби убрать?','Не убирать и не округлять. Опиши диапазон.'],'Принимать давление строго больше -35 и не больше -9. Дробные значения сохранять без округления.','Допустимое давление')
add('sort-with-rule',['Отсортировать -27, -8, -16, -8, сохранив количество элементов.','Сначала самый маленький?','Нет, самый большой.','Один из -8 удалить?','Не удалять.','Что включить в задачу?','Правило сортировки и весь итоговый список.'],'Сортировать по убыванию с сохранением повторов. Итоговый список: -8, -8, -16, -27.','Сортировка списка')
add('destination-not-guessed',['Подготовить уведомление о ремонте. Получателя назову позже.','Отправлять последнему арендатору?','Нет, его не выбирай.','Тогда владельцу?','Я ещё никого не выбрал.','Сейчас что делать?','Только подготовить, никому не отправлять. В задаче спроси, кто получатель.'],'Подготовить уведомление о ремонте. Получатель не выбран; пока никому не отправлять.','Уведомление о ремонте',['Кто должен получить уведомление о ремонте?'])
add('quoted-ban-not-action',['В памятку включить пример «не публикуй отчёт». Саму памятку редактору отправить разрешаю.','Пример отменяет отправку?','Нет, это цитата, не команда.','Удалить цитату?','Нет.','Какой итог?','Пример оставить, разрешение отправки редактору тоже оставить.'],'Сохранить в памятке пример «не публикуй отчёт». Отправка памятки редактору разрешена; цитата это разрешение не отменяет.','Пример в памятке')
add('restricted-version',['Полный протокол: номер осмотра и комментарии. Арендатору его не отправлять.','Краткий можно?','Краткий с одним номером осмотра разрешаю отправить. Комментарии исключить.','Разрешение относится к полному?','Нет, полный по-прежнему запрещён.','Номер осмотра нужен в обоих?','Да. Составь задачу для обеих версий.'],'Полный протокол содержит номер осмотра и комментарии; арендатору его не отправлять. Краткий протокол содержит номер осмотра без комментариев; его отправка арендатору разрешена.','Версии протокола')
add('reversed-undo',['Убрать поле pager, сохранить поле mobile.','Поле pager удаляем?','Отменяю это удаление.','Теперь сохранить оба?','Нет, отмену отзываю: pager удалить.','mobile тоже удалить?','Не удалять. Оформи.'],'Удалить поле pager, поле mobile сохранить.','Поля связи')
add('service-unselected',['При ошибке резервного копирования уведомить администратора: имя копии и причина.','Через email?','Это ещё не выбрано.','Саму копию приложить?','Нет, без вложений.','При успехе тоже?','Нет. Составь задачу и вопрос о способе связи.'],'Только при ошибке резервного копирования уведомлять администратора, передавать имя копии и причину без вложений. При успехе не уведомлять. Способ связи не выбран.','Ошибка резервного копирования',['Каким способом уведомлять администратора?'])
add('single-use-scope',['Нужен одноразовый код получения посылки.','Срок 120 секунд?','Нет, согласую 135 секунд.','Можно получить ещё одну посылку тем же кодом?','Нельзя, код используется один раз.','Привязать к входу в аккаунт?','Нет. Опиши только получение посылки и эти ограничения.'],'Реализовать одноразовый код получения посылки со сроком действия 135 секунд. Повторное использование запрещено. К входу в аккаунт не привязывать.','Код получения посылки')
add('view-not-storage',['На экране выводить parcel_id вместо order_id.','Удалить order_id из хранилища?','Хранилище не трогать.','Оба поля вывести?','Нет, только parcel_id.','Миграция нужна?','Нет, менять только выбор поля на экране. Оформи.'],'На экране выводить только parcel_id вместо order_id. Хранилище не изменять, миграцию не выполнять.','Поле на экране')
sig=lambda x:json.dumps(x['messages'][:-1],sort_keys=True,ensure_ascii=False)
history=[x for p in R.parent.glob('requirements-draft-*/*.jsonl') if p!=R/'release-dialogues.jsonl' for x in read(p) if 'messages' in x]
assert len(rows)==16 and len(set(map(sig,rows)))==16 and set(map(sig,rows)).isdisjoint(map(sig,history))
p=R/'release-dialogues.jsonl';p.write_text(''.join(json.dumps(x,ensure_ascii=False)+'\n' for x in rows))
(R/'release-dialogues-protocol.json').write_text(json.dumps({'data_sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'count':16,'training_use':False,'gate':'All sixteen final requirement sets correct, no lost parent successes; real runtime and generated multi-turn evaluation additionally required.','review':'Non-blind manual semantics; preserve explicit exclusions, requested questions, exact labels and accurate headings. Equivalent wording accepted. Cosmetic phrasing recorded separately.','limits':'Synthetic fixed histories in known failure categories; not broad reliability evidence.'},indent=2)+'\n')
print('Reserved 16 new diverse dialogues')
